program='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    markers = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                markers.setdefault(grid[r][c], []).append((r, c))
    for color, pts in markers.items():
        for r in range(h):
            cols = [c for rr, c in pts if rr == r]
            if len(cols) >= 2:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 3
        for c in range(w):
            rows = [r for r, cc in pts if cc == c]
            if len(rows) >= 2:
                for r in range(min(rows), max(rows) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    return out
'''
